package com.shoprestockalert;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class RestockTrackerTest
{
	private static final int KNIFE = 946;
	private static final int LOBSTER = 379;
	private static final int BOLTS = 9245;

	private static final Map<Integer, Integer> NONE = null;

	private static Map<Integer, Integer> stock(Object... pairs)
	{
		Map<Integer, Integer> map = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			map.put((Integer) pairs[i], (Integer) pairs[i + 1]);
		}
		return map;
	}

	@Test
	public void firstSnapshotIsOnlyABaseline()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(10);
		assertTrue(tracker.update(10, stock(KNIFE, 3), NONE).isEmpty());
		assertFalse(tracker.getTimer().hasPhase());
	}

	@Test
	public void learnsIntervalFromTwoTimerTicks()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		assertEquals(Collections.singletonList(KNIFE), tracker.update(40, stock(KNIFE, 4), NONE));
		ShopTimer timer = tracker.getTimer();
		assertFalse(timer.hasInterval());
		// only the phase is known, so the fallback interval is used
		assertEquals(140, timer.nextChangeTick(50, 100));

		tracker.update(140, stock(KNIFE, 5), NONE);
		assertEquals(100, timer.getInterval());
		assertEquals(240, timer.nextChangeTick(141, 30));
		assertEquals(240, timer.nextChangeTick(240, 30));
		assertEquals(340, timer.nextChangeTick(241, 30));
	}

	@Test
	public void wholeShopMovingTogetherIsOneObservation()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3, BOLTS, 10, LOBSTER, 5), NONE);
		assertEquals(Arrays.asList(KNIFE, BOLTS, LOBSTER).size(), tracker.update(65, stock(KNIFE, 4, BOLTS, 11, LOBSTER, 4), NONE).size());
		tracker.update(165, stock(KNIFE, 5, BOLTS, 12, LOBSTER, 3), NONE);
		assertEquals(100, tracker.getTimer().getInterval());
		assertEquals(165, tracker.getTimer().getLastChangeTick());
	}

	@Test
	public void ownTradeIsNotATimerTick()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		assertTrue(tracker.update(5, stock(KNIFE, 2), stock(KNIFE, -1)).isEmpty());
		assertTrue(tracker.update(6, stock(KNIFE, 2, LOBSTER, 10), stock(LOBSTER, 10)).isEmpty());
		assertEquals(10, tracker.get(LOBSTER).getSold());
		assertEquals(10, tracker.soldRemaining());
		assertFalse(tracker.getTimer().hasPhase());
	}

	@Test
	public void timerSurvivesTheLastSoldItemDrainingAway()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		// sell one lobster, the only thing in the shop that will move
		tracker.update(1, stock(KNIFE, 3, LOBSTER, 1), stock(LOBSTER, 1));
		assertEquals(Collections.singletonList(LOBSTER), tracker.update(50, stock(KNIFE, 3), NONE));
		assertNull(tracker.get(LOBSTER));
		assertEquals(0, tracker.soldRemaining());
		assertTrue(tracker.getTimer().hasPhase());
		assertEquals(150, tracker.getTimer().nextChangeTick(60, 100));
		// selling again later uses the phase already known
		tracker.update(120, stock(KNIFE, 3, LOBSTER, 2), stock(LOBSTER, 2));
		assertEquals(2, tracker.get(LOBSTER).getSold());
		assertEquals(150, tracker.getTimer().nextChangeTick(121, 100));
		assertEquals(Collections.singletonList(LOBSTER), tracker.update(150, stock(KNIFE, 3, LOBSTER, 1), NONE));
		assertEquals(100, tracker.getTimer().getInterval());
		assertEquals(1, tracker.get(LOBSTER).getSold());
	}

	@Test
	public void sellingOnTheRestockTickStillCountsTheTick()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3, LOBSTER, 4), NONE);
		tracker.update(1, stock(KNIFE, 3, LOBSTER, 4), stock(LOBSTER, 0));
		// at tick 100 we sell 5 more lobsters and the timer drains one at the same moment: +5 -1 = +4
		assertEquals(Collections.singletonList(LOBSTER), tracker.update(100, stock(KNIFE, 3, LOBSTER, 8), stock(LOBSTER, 5)));
		assertEquals(4, tracker.get(LOBSTER).getSold());
		assertEquals(100, tracker.getTimer().getLastChangeTick());
		// selling something else on the tick does not hide the knife restocking either
		assertEquals(Collections.singletonList(KNIFE), tracker.update(200, stock(KNIFE, 4, LOBSTER, 18), stock(LOBSTER, 10)));
		assertEquals(100, tracker.getTimer().getInterval());
	}

	@Test
	public void bulkChangeIsAnotherPlayer()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 5), NONE);
		assertTrue(tracker.update(7, stock(KNIFE, 1), NONE).isEmpty());
		assertEquals(1, tracker.get(KNIFE).getQuantity());
		assertFalse(tracker.getTimer().hasPhase());
	}

	@Test
	public void offScheduleSingleChangeDoesNotMovePhase()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		tracker.update(100, stock(KNIFE, 4), NONE);
		tracker.update(200, stock(KNIFE, 5), NONE);
		ShopTimer timer = tracker.getTimer();
		assertEquals(100, timer.getInterval());
		// someone bought one at 230
		assertTrue(tracker.update(230, stock(KNIFE, 4), NONE).isEmpty());
		assertEquals(300, timer.nextChangeTick(231, 100));
		// and the real tick still lands at 300
		assertEquals(Collections.singletonList(KNIFE), tracker.update(300, stock(KNIFE, 5), NONE));
	}

	@Test
	public void twoStrikesRelearnTheInterval()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		tracker.update(100, stock(KNIFE, 4), NONE);
		tracker.update(200, stock(KNIFE, 5), NONE);
		tracker.update(230, stock(KNIFE, 6), NONE);
		tracker.update(260, stock(KNIFE, 7), NONE);
		assertEquals(60, tracker.getTimer().getInterval());
		assertEquals(260, tracker.getTimer().getLastChangeTick());
	}

	@Test
	public void reopeningKeepsIntervalAndResyncsPhase()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		tracker.update(100, stock(KNIFE, 4), NONE);
		tracker.update(200, stock(KNIFE, 5), NONE);
		tracker.stopObserving();
		// while closed the prediction carries on from the last seen tick
		assertEquals(500, tracker.getTimer().nextChangeTick(450, 100));
		tracker.startObserving(450);
		tracker.update(450, stock(KNIFE, 2), NONE);
		assertEquals(Collections.singletonList(KNIFE), tracker.update(501, stock(KNIFE, 3), NONE));
		assertEquals(100, tracker.getTimer().getInterval());
		assertEquals(601, tracker.getTimer().nextChangeTick(502, 100));
	}

	@Test
	public void missedTicksOnlyCountWhileSoldStockShouldBeDraining()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		tracker.update(100, stock(KNIFE, 4), NONE);
		tracker.update(200, stock(KNIFE, 5), NONE);
		// nothing sold: a fully stocked shop sits still and the phase is kept
		for (int now = 201; now <= 500; now++)
		{
			assertFalse(tracker.tick(now, 100));
		}
		assertTrue(tracker.getTimer().hasPhase());

		// sold stock that fails to drain on three predicted ticks means the phase is wrong
		tracker.update(510, stock(KNIFE, 5, LOBSTER, 3), stock(LOBSTER, 3));
		boolean dropped = false;
		for (int now = 511; now <= 905 && !dropped; now++)
		{
			dropped = tracker.tick(now, 100);
		}
		assertTrue(dropped);
		assertFalse(tracker.getTimer().hasPhase());
		// the sold count is still known so it can be re-timed
		assertEquals(3, tracker.get(LOBSTER).getSold());
	}

	@Test
	public void veryShortGapsAreNotLearned()
	{
		RestockTracker tracker = new RestockTracker();
		tracker.startObserving(0);
		tracker.update(0, stock(KNIFE, 3), NONE);
		tracker.update(10, stock(KNIFE, 4), NONE);
		tracker.update(12, stock(KNIFE, 5), NONE);
		assertFalse(tracker.getTimer().hasInterval());
	}

	@Test
	public void overlayFormats()
	{
		assertEquals("now", RestockOverlay.formatTicks(0, true, true));
		assertEquals("12t", RestockOverlay.formatTicks(12, true, false));
		assertEquals("~12t 7.2s", RestockOverlay.formatTicks(12, false, true));
		assertEquals("45s", RestockOverlay.formatDuration(75));
		assertEquals("12.5m", RestockOverlay.formatDuration(1250));
	}
}

package com.shoprestockalert;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

// ./gradlew run, or run this from the IDE with -ea
public class ShopRestockAlertLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ShopRestockAlertPlugin.class);
		RuneLite.main(args);
	}
}

package com.shoprestockalert;

import com.google.inject.Provides;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Shop Restock Alert",
	description = "Times shop restock ticks, counts down with dings and shows when sold items clear so you can plan around the next restock",
	tags = {"shop", "restock", "stock", "timer", "tick", "sell", "alert", "store"}
)
public class ShopRestockAlertPlugin extends Plugin
{
	// keep in sync with build.gradle
	public static final String VERSION = "1.0.1";

	// getTicksToNext() when there is no timer to predict from
	public static final int NO_TIMER = -1;

	private static final Logger log = LoggerFactory.getLogger(ShopRestockAlertPlugin.class);

	private static final int TICKS_PER_MINUTE = 100;
	// our inventory update and the shop update for the same trade can land a tick apart
	private static final int OWN_TRADE_WINDOW = 1;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ShopRestockAlertConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RestockOverlay overlay;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Notifier notifier;

	private final RestockTracker tracker = new RestockTracker();
	private RestockInfoBox infoBox;

	private volatile boolean shopOpen;
	// container id of the shop we are tracking, -1 until a shop has sent stock
	private int shopContainerId = -1;
	// latest shop stock received, evaluated a tick later so our own trades can be told apart
	private Map<Integer, Integer> pendingStock;
	private int pendingTick = -1;
	// stock from a container that arrived while no shop was open, in case the shop interface follows it
	private Map<Integer, Integer> candidateStock;
	private int candidateId = -1;
	private int candidateTick = -1;
	// our inventory by canonical item id, and what recently changed in it, so our trades can be subtracted per item
	private Map<Integer, Integer> inventorySnapshot;
	private final Deque<InventoryChange> inventoryChanges = new ArrayDeque<>();
	// where we were standing when the shop was last opened, null once forgotten
	private WorldPoint shopLocation;
	private int lastSoundTick = -1;
	private int lastRestockAlertTick = -1;

	// what the overlay and infobox draw, refreshed every game tick
	private volatile int ticksToNext = NO_TIMER;
	private volatile int intervalTicks;
	private volatile boolean intervalLearned;
	private volatile List<RestockRow> rows = Collections.emptyList();

	private static class InventoryChange
	{
		final int tick;
		final Map<Integer, Integer> deltas;

		InventoryChange(int tick, Map<Integer, Integer> deltas)
		{
			this.tick = tick;
			this.deltas = deltas;
		}
	}

	@Provides
	ShopRestockAlertConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ShopRestockAlertConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		infoBox = new RestockInfoBox(itemManager.getImage(ItemID.COINS), this, config);
		infoBoxManager.addInfoBox(infoBox);
		clientThread.invoke(() ->
		{
			shopOpen = client.getWidget(InterfaceID.Shopmain.ITEMS) != null;
			if (shopOpen)
			{
				tracker.startObserving(client.getTickCount());
			}
			if (client.getItemContainer(InventoryID.INV) != null)
			{
				inventorySnapshot = canonicalSnapshot(client.getItemContainer(InventoryID.INV).getItems());
			}
		});
		log.info("Shop Restock Alert started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		if (infoBox != null)
		{
			infoBoxManager.removeInfoBox(infoBox);
			infoBox = null;
		}
		reset();
		log.info("Shop Restock Alert stopped");
	}

	private void reset()
	{
		tracker.clear();
		shopOpen = false;
		shopContainerId = -1;
		pendingStock = null;
		pendingTick = -1;
		candidateStock = null;
		candidateId = -1;
		candidateTick = -1;
		inventorySnapshot = null;
		inventoryChanges.clear();
		shopLocation = null;
		lastSoundTick = -1;
		lastRestockAlertTick = -1;
		ticksToNext = NO_TIMER;
		intervalTicks = 0;
		intervalLearned = false;
		rows = Collections.emptyList();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.HOPPING || state == GameState.LOGIN_SCREEN || state == GameState.CONNECTION_LOST)
		{
			// shop timers are per world, so nothing we know carries over
			reset();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.SHOPMAIN)
		{
			return;
		}
		shopOpen = true;
		int now = client.getTickCount();
		Player local = client.getLocalPlayer();
		shopLocation = local == null ? null : local.getWorldLocation();
		// the stock container usually arrives just before the interface does, so adopt it
		if (candidateStock != null && candidateTick >= now - 1)
		{
			adoptShop(candidateId, now);
			pendingStock = candidateStock;
			pendingTick = candidateTick;
		}
		else
		{
			tracker.startObserving(now);
		}
		candidateStock = null;
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() != InterfaceID.SHOPMAIN)
		{
			return;
		}
		shopOpen = false;
		flushPending();
		tracker.stopObserving();
		if (!config.keepAfterClose())
		{
			tracker.clear();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		int now = client.getTickCount();
		if (event.getItemContainer() == null)
		{
			return;
		}
		if (id == InventoryID.INV)
		{
			recordInventoryChange(now, event.getItemContainer().getItems());
			return;
		}
		if (id == InventoryID.WORN || id == InventoryID.BANK)
		{
			return;
		}
		Map<Integer, Integer> stock = snapshot(event.getItemContainer().getItems());
		if (!shopOpen)
		{
			// not a shop we can see. Keep it briefly in case the shop interface opens right after
			candidateStock = stock;
			candidateId = id;
			candidateTick = now;
			return;
		}
		if (id != shopContainerId)
		{
			adoptShop(id, now);
		}
		if (pendingStock != null && pendingTick != now)
		{
			// a new tick's worth of changes: settle the earlier one first so the phases stay separate
			flushPending();
		}
		pendingStock = stock;
		pendingTick = now;
	}

	// a shop container we have not been tracking: forget the old shop's timer and start watching this one
	private void adoptShop(int containerId, int now)
	{
		if (containerId != shopContainerId)
		{
			tracker.clear();
			shopContainerId = containerId;
		}
		tracker.startObserving(now);
	}

	private void recordInventoryChange(int now, Item[] items)
	{
		Map<Integer, Integer> current = canonicalSnapshot(items);
		if (inventorySnapshot != null)
		{
			Map<Integer, Integer> deltas = new HashMap<>();
			Set<Integer> ids = new HashSet<>(inventorySnapshot.keySet());
			ids.addAll(current.keySet());
			for (int itemId : ids)
			{
				int delta = current.getOrDefault(itemId, 0) - inventorySnapshot.getOrDefault(itemId, 0);
				if (delta != 0)
				{
					deltas.put(itemId, delta);
				}
			}
			if (!deltas.isEmpty())
			{
				inventoryChanges.addLast(new InventoryChange(now, deltas));
			}
		}
		inventorySnapshot = current;
		// anything older than the matching window can never pair with a shop update now
		while (!inventoryChanges.isEmpty() && inventoryChanges.peekFirst().tick < now - OWN_TRADE_WINDOW - 1)
		{
			inventoryChanges.removeFirst();
		}
	}

	// what our own trades around the given tick did to the shop's stock: inventory losses are shop gains
	private Map<Integer, Integer> ownTradesAround(int tick)
	{
		Map<Integer, Integer> own = new HashMap<>();
		Iterator<InventoryChange> it = inventoryChanges.iterator();
		while (it.hasNext())
		{
			InventoryChange change = it.next();
			if (Math.abs(change.tick - tick) > OWN_TRADE_WINDOW)
			{
				continue;
			}
			for (Map.Entry<Integer, Integer> entry : change.deltas.entrySet())
			{
				own.merge(entry.getKey(), -entry.getValue(), Integer::sum);
			}
			// each trade explains one shop update only
			it.remove();
		}
		own.values().removeIf(delta -> delta == 0);
		return own;
	}

	private void flushPending()
	{
		if (pendingStock == null)
		{
			return;
		}
		Map<Integer, Integer> own = ownTradesAround(pendingTick);
		if (!own.isEmpty())
		{
			log.debug("own trades around {}: {}", pendingTick, own);
		}
		List<Integer> moved = tracker.update(pendingTick, pendingStock, own);
		if (!moved.isEmpty())
		{
			log.debug("restock tick at {} moved {}", pendingTick, moved);
		}
		pendingStock = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int now = client.getTickCount();
		// wait a tick so an inventory update from the same trade has had time to arrive
		if (pendingStock != null && now > pendingTick + OWN_TRADE_WINDOW - 1)
		{
			flushPending();
		}
		if (tracker.tick(now, config.defaultInterval()))
		{
			log.debug("dropped the timer after predicted ticks that never came");
		}

		int forgetTicks = config.forgetAfter() * TICKS_PER_MINUTE;
		if (tracker.getLastObservationTick() != RestockTracker.UNKNOWN && now - tracker.getLastObservationTick() > forgetTicks)
		{
			forget("no restock tick seen for " + config.forgetAfter() + " minutes");
		}
		if (!shopOpen && leftTheShop())
		{
			forget("walked away from the shop");
		}

		refresh(now);
		alert(now);
	}

	// with the shop closed, are we far enough from where we opened it that its timer is no longer of interest
	private boolean leftTheShop()
	{
		int limit = config.forgetDistance();
		Player local = client.getLocalPlayer();
		if (limit <= 0 || shopLocation == null || local == null)
		{
			return false;
		}
		WorldPoint here = local.getWorldLocation();
		return here == null || here.getPlane() != shopLocation.getPlane() || here.distanceTo2D(shopLocation) > limit;
	}

	// drop everything about the current shop; the overlays go with it until a shop is opened again
	private void forget(String why)
	{
		if (tracker.getTimer().hasPhase() || !tracker.allItems().isEmpty())
		{
			log.debug("forgetting shop timer: {}", why);
		}
		tracker.clear();
		shopContainerId = -1;
		shopLocation = null;
		pendingStock = null;
	}

	private void refresh(int now)
	{
		ShopTimer timer = tracker.getTimer();
		int next = timer.nextChangeTick(now, config.defaultInterval());
		int left = next == ShopTimer.UNKNOWN ? NO_TIMER : next - now;
		ticksToNext = left;
		intervalTicks = timer.stepOr(config.defaultInterval());
		intervalLearned = timer.hasInterval();

		List<RestockRow> result = new ArrayList<>();
		for (TrackedItem item : tracker.allItems())
		{
			int clearTicks = RestockRow.UNKNOWN;
			if (item.getSold() > 0 && left != NO_TIMER)
			{
				clearTicks = left + (item.getSold() - 1) * intervalTicks;
			}
			result.add(new RestockRow(item.getItemId(), itemName(item.getItemId()), item.getQuantity(), item.getSold(), clearTicks));
		}
		// items we sold first, most left to clear first
		result.sort((a, b) -> Integer.compare(b.getSold(), a.getSold()));
		rows = Collections.unmodifiableList(result);
	}

	private boolean alertsWanted()
	{
		switch (config.alertMode())
		{
			case WHILE_SOLD:
				return tracker.soldRemaining() > 0;
			case SHOP_OPEN:
				return shopOpen;
			default:
				return true;
		}
	}

	private void alert(int now)
	{
		int left = ticksToNext;
		if (left == NO_TIMER || !alertsWanted())
		{
			return;
		}
		if (left <= 0)
		{
			if (lastRestockAlertTick != now)
			{
				lastRestockAlertTick = now;
				play(config.restockSound(), now);
				notifier.notify(config.restockNotification(), "Shop restock tick");
			}
		}
		else if (left <= config.countdownTicks())
		{
			play(config.countdownSound(), now);
		}
	}

	private void play(int soundId, int now)
	{
		if (soundId <= 0 || config.soundVolume() <= 0 || lastSoundTick == now)
		{
			return;
		}
		lastSoundTick = now;
		// the two argument form plays even when in-game sound effects are muted
		client.playSoundEffect(soundId, config.soundVolume());
	}

	// inventory contents keyed by the unnoted item id, since selling notes puts the plain item in the shop
	private Map<Integer, Integer> canonicalSnapshot(Item[] items)
	{
		Map<Integer, Integer> stock = new HashMap<>();
		if (items == null)
		{
			return stock;
		}
		for (Item item : items)
		{
			if (item != null && item.getId() > 0 && item.getId() != ItemID.COINS)
			{
				stock.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		return stock;
	}

	private static Map<Integer, Integer> snapshot(Item[] items)
	{
		Map<Integer, Integer> stock = new HashMap<>();
		if (items == null)
		{
			return stock;
		}
		for (Item item : items)
		{
			if (item != null && item.getId() > 0)
			{
				stock.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return stock;
	}

	private String itemName(int itemId)
	{
		ItemComposition composition = itemManager.getItemComposition(itemId);
		String name = composition == null ? null : composition.getName();
		return name == null || "null".equals(name) ? "Item " + itemId : name;
	}

	public int getTicksToNext()
	{
		return ticksToNext;
	}

	public int getIntervalTicks()
	{
		return intervalTicks;
	}

	public boolean isIntervalLearned()
	{
		return intervalLearned;
	}

	public List<RestockRow> getRows()
	{
		return rows;
	}

	public boolean isShopOpen()
	{
		return shopOpen;
	}
}

