package com.shoprestockalert;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Diffs successive snapshots of a shop's stock, keeps the shop's timer and the items we sold into it.
 * Pure Java so it can be unit tested. Ticks are the client tick counter.
 */
public class RestockTracker
{
	public static final int UNKNOWN = ShopTimer.UNKNOWN;

	private final ShopTimer timer = new ShopTimer();
	private final Map<Integer, TrackedItem> items = new LinkedHashMap<>();
	private Map<Integer, Integer> lastSnapshot;
	private int observingSince = UNKNOWN;
	private int lastObservationTick = UNKNOWN;

	// the shop interface opened: from here on every stock change is seen
	public void startObserving(int tick)
	{
		observingSince = tick;
		lastSnapshot = null;
	}

	// the shop interface closed: stock can change unseen, so the next snapshot is a fresh baseline
	public void stopObserving()
	{
		observingSince = UNKNOWN;
		lastSnapshot = null;
	}

	public boolean isObserving()
	{
		return observingSince != UNKNOWN;
	}

	public void clear()
	{
		timer.clear();
		items.clear();
		lastSnapshot = null;
		observingSince = UNKNOWN;
		lastObservationTick = UNKNOWN;
	}

	public ShopTimer getTimer()
	{
		return timer;
	}

	public int getLastObservationTick()
	{
		return lastObservationTick;
	}

	/**
	 * Feed a new stock snapshot (item id to quantity). ownTrades is what our own buying and selling around this
	 * tick did to the shop, item id to change in shop stock (positive when we sold), so it can be subtracted
	 * before deciding what the timer did. Returns the ids the timer moved.
	 */
	public List<Integer> update(int tick, Map<Integer, Integer> stock, Map<Integer, Integer> ownTrades)
	{
		List<Integer> moved = new ArrayList<>();
		if (lastSnapshot == null)
		{
			lastSnapshot = new HashMap<>(stock);
			for (TrackedItem item : items.values())
			{
				item.setQuantity(stock.getOrDefault(item.getItemId(), 0));
			}
			forgetGone(stock);
			return moved;
		}

		Set<Integer> ids = new HashSet<>(lastSnapshot.keySet());
		ids.addAll(stock.keySet());
		for (int id : ids)
		{
			int before = lastSnapshot.getOrDefault(id, 0);
			int after = stock.getOrDefault(id, 0);
			int delta = after - before;
			if (delta == 0)
			{
				continue;
			}
			TrackedItem item = items.computeIfAbsent(id, TrackedItem::new);
			item.setQuantity(after);
			int own = ownTrades == null ? 0 : ownTrades.getOrDefault(id, 0);
			if (own != 0)
			{
				item.addSold(own);
				delta -= own;
				if (delta == 0)
				{
					continue;
				}
			}
			if (Math.abs(delta) != 1)
			{
				// someone else bought or sold a stack
				continue;
			}
			if (delta < 0)
			{
				item.addSold(-1);
			}
			moved.add(id);
		}

		// every item moves on the same tick, so one observation covers them all
		if (!moved.isEmpty() && timer.observe(tick, observingSince))
		{
			lastObservationTick = tick;
		}
		else
		{
			moved.clear();
		}

		forgetGone(stock);
		lastSnapshot = new HashMap<>(stock);
		return moved;
	}

	// an item that left the shop entirely (sold stock that ran out) has nothing left to track
	private void forgetGone(Map<Integer, Integer> stock)
	{
		items.values().removeIf(item -> !stock.containsKey(item.getItemId()));
	}

	/**
	 * Call once per game tick while observing. If something we sold should have drained on a predicted tick and
	 * did not, twice in a row, the phase is wrong and gets dropped. Returns true when that happened.
	 */
	public boolean tick(int now, int fallbackInterval)
	{
		if (!isObserving() || !timer.hasPhase() || soldRemaining() == 0)
		{
			return false;
		}
		return timer.checkExpected(now, fallbackInterval);
	}

	public int soldRemaining()
	{
		int total = 0;
		for (TrackedItem item : items.values())
		{
			total += item.getSold();
		}
		return total;
	}

	public TrackedItem get(int itemId)
	{
		return items.get(itemId);
	}

	public List<TrackedItem> allItems()
	{
		return Collections.unmodifiableList(new ArrayList<>(items.values()));
	}

	public List<TrackedItem> soldItems()
	{
		List<TrackedItem> result = new ArrayList<>();
		for (TrackedItem item : items.values())
		{
			if (item.getSold() > 0)
			{
				result.add(item);
			}
		}
		return Collections.unmodifiableList(result);
	}
}

package com.shoprestockalert;

/**
 * The restock timer of one shop. Every item in the shop moves on the same tick, so one phase and one interval
 * describe the whole shop, and they outlive the items that revealed them.
 */
public class ShopTimer
{
	public static final int UNKNOWN = -1;

	// a gap this far off a multiple of the interval still counts as the same timer
	private static final int TOLERANCE = 1;
	private static final int STRIKES_TO_FORGET = 2;
	// two player trades a few ticks apart must not be mistaken for the timer
	private static final int MIN_INTERVAL = 5;
	// predicted ticks that came and went without the sold stock moving before the phase is dropped
	static final int MISSES_TO_FORGET = 3;

	private int lastChangeTick = UNKNOWN;
	private int interval = UNKNOWN;
	private int strikes;
	private int expectedTick = UNKNOWN;
	private int misses;

	public int getLastChangeTick()
	{
		return lastChangeTick;
	}

	public int getInterval()
	{
		return interval;
	}

	public boolean hasInterval()
	{
		return interval != UNKNOWN;
	}

	public boolean hasPhase()
	{
		return lastChangeTick != UNKNOWN;
	}

	public int getMisses()
	{
		return misses;
	}

	public void clear()
	{
		lastChangeTick = UNKNOWN;
		interval = UNKNOWN;
		strikes = 0;
		expectedTick = UNKNOWN;
		misses = 0;
	}

	/**
	 * The timer moved stock at the given tick. observingSince is the tick we have been watching the shop
	 * continuously from, or UNKNOWN. Returns false when the change does not fit the known timer and was ignored.
	 */
	boolean observe(int tick, int observingSince)
	{
		if (lastChangeTick != UNKNOWN)
		{
			int gap = tick - lastChangeTick;
			if (gap <= 0)
			{
				return false;
			}
			boolean watchedWholeGap = observingSince != UNKNOWN && lastChangeTick >= observingSince;
			if (interval == UNKNOWN)
			{
				if (watchedWholeGap && gap >= MIN_INTERVAL)
				{
					interval = gap;
				}
			}
			else if (!fitsInterval(gap, interval))
			{
				// probably another player trading one, unless it keeps happening
				strikes++;
				if (strikes >= STRIKES_TO_FORGET)
				{
					strikes = 0;
					interval = watchedWholeGap && gap >= MIN_INTERVAL ? gap : UNKNOWN;
					lastChangeTick = tick;
				}
				return false;
			}
			else
			{
				strikes = 0;
			}
		}
		lastChangeTick = tick;
		misses = 0;
		expectedTick = UNKNOWN;
		return true;
	}

	static boolean fitsInterval(int gap, int interval)
	{
		int remainder = gap % interval;
		return remainder <= TOLERANCE || interval - remainder <= TOLERANCE;
	}

	/**
	 * Called every tick while the shop is open and something in it must move on the next tick.
	 * Counts predicted ticks that never came. Returns true when the phase should be forgotten.
	 */
	boolean checkExpected(int now, int fallbackInterval)
	{
		if (expectedTick != UNKNOWN && now > expectedTick + TOLERANCE)
		{
			expectedTick = UNKNOWN;
			misses++;
			if (misses >= MISSES_TO_FORGET)
			{
				clear();
				return true;
			}
		}
		if (expectedTick == UNKNOWN && nextChangeTick(now, fallbackInterval) == now)
		{
			expectedTick = now;
		}
		return false;
	}

	/**
	 * Tick of the next timer move, using fallback when the interval has not been learned yet. UNKNOWN when never seen.
	 */
	public int nextChangeTick(int now, int fallbackInterval)
	{
		if (lastChangeTick == UNKNOWN)
		{
			return UNKNOWN;
		}
		int step = stepOr(fallbackInterval);
		if (step <= 0)
		{
			return UNKNOWN;
		}
		int elapsed = now - lastChangeTick;
		if (elapsed <= 0)
		{
			return lastChangeTick + step;
		}
		int periods = (elapsed + step - 1) / step;
		return lastChangeTick + periods * step;
	}

	public int stepOr(int fallbackInterval)
	{
		return interval != UNKNOWN ? interval : fallbackInterval;
	}
}

